  z-index: 50;
}

.z-modal-overlay {
  z-index: 60;
}

.z-modal-content {
  z-index: 61;
}

.z-toast {
  z-index: 100;
}

/* Prevent body scroll when modal is open */
.modal-open {
  overflow: hidden;
  padding-right: var(--scrollbar-width, 0);
}

/* Consistent backdrop styling */
.overlay-backdrop {
  background-color: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(4px);
}

/* Fix for mobile viewport issues */
@supports (height: 100dvh) {
  .min-h-screen {
    min-height: 100dvh;
  }
}

/* Mobile touch target sizing - minimum 44x44px */
@media (max-width: 768px) {
  .touch-target,
  button:not(.no-touch-target),
  a:not(.no-touch-target),
  [role="button"]:not(.no-touch-target) {
    min-width: 44px;
    min-height: 44px;
  }

  /* Gallery dots - proper touch size */
  .image-indicator {
    min-width: 44px;
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .image-indicator > * {
    width: 12px;
    height: 12px;
  }

  /* Size and color selectors */
  .size-selector,
  .color-selector {
    min-width: 44px;
    min-height: 44px;
    padding: 8px 12px;
  }
}

/* Onboarding Styles */
@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.onboarding-container {
  min-height: 100vh;
  background-color: var(--onboarding-bg);
}

.onboarding-screen-enter {
  animation: slideInRight 0.3s ease-out;
}

.onboarding-screen-exit {
  animation: slideInLeft 0.3s ease-out;
}

/* Onboarding circular arrow button */
.onboarding-next-button {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background-color: var(--onboarding-primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.onboarding-next-button:hover:not(:disabled) {
  background-color: var(--onboarding-primary-hover);
  transform: scale(1.05);
}

.onboarding-next-button:disabled {
  background-color: #D1D5DB;
  cursor: not-allowed;
}

/* Style carousel custom scrollbar */
.embla {
  overflow: hidden;
}

.embla__container {
  display: flex;
  gap: 1rem;
}

.embla__slide {
  flex: 0 0 280px;
  min-width: 0;
}

