import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { Loader2 } from 'lucide-react'

import { cn } from '@/lib/utils'

/**
 * OOTDay Button Component
 *
 * @description Button component with fashion brand styling and accessibility features
 * @example
 * <Button variant="primary" size="md">Shop Now</Button>
 * <Button variant="secondary" loading>Processing...</Button>
 */

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium transition-all duration-200 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive min-h-[44px] min-w-[44px]",
  {
    variants: {
      variant: {
        primary:
          'bg-primary-500 text-white shadow-sm hover:bg-primary-600 active:bg-primary-700 focus-visible:ring-primary-500',
        secondary:
          'bg-secondary-500 text-white shadow-sm hover:bg-secondary-600 active:bg-secondary-700 focus-visible:ring-secondary-500',
        outline:
          'border-2 border-primary-500 bg-transparent text-primary-500 shadow-sm hover:bg-primary-50 active:bg-primary-100 focus-visible:ring-primary-500 dark:hover:bg-primary-900/20 dark:active:bg-primary-900/30',
        ghost:
          'bg-transparent text-primary-500 hover:bg-primary-50 active:bg-primary-100 focus-visible:ring-primary-500 dark:hover:bg-primary-900/20 dark:active:bg-primary-900/30',
        destructive:
          'bg-error text-white shadow-sm hover:bg-red-600 active:bg-red-700 focus-visible:ring-error',
        link: 'text-primary-500 underline-offset-4 hover:underline focus-visible:ring-primary-500',
      },
      size: {
        sm: 'h-8 px-3 text-sm min-h-[44px] min-w-[44px]',
        md: 'h-10 px-4 text-base min-h-[44px] min-w-[44px]',
        lg: 'h-12 px-6 text-lg min-h-[44px] min-w-[44px]',
        icon: 'size-10 min-h-[44px] min-w-[44px]',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
    },
  },
)

export interface ButtonProps
  extends React.ComponentProps<'button'>,
    VariantProps<typeof buttonVariants> {
  /** Render as a child component */
  asChild?: boolean
  /** Show loading spinner */
  loading?: boolean
  /** Icon to display */
  icon?: React.ReactNode
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, loading = false, icon, children, disabled, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    const isDisabled = disabled || loading

    return (
      <Comp
        ref={ref}
        className={cn(buttonVariants({ variant, size, className }))}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        data-loading={loading}
        {...props}
      >
        {loading && <Loader2 className="size-4 animate-spin" />}
        {!loading && icon && icon}
        {children}
      </Comp>
    )
  }
)

Button.displayName = 'Button'

export { Button, buttonVariants }

